<template><Card title="Horizontal" description="The same anatomy creates a horizontally scrollable timeline."><Timeline orientation="horizontal" aria-label="Order progress"><TimelineItem v-for="(label,index) in labels" :key="label" :status="index < 2 ? 'completed' : index === 2 ? 'current' : 'pending'"><TimelineOpposite>Step {{ index+1 }}</TimelineOpposite><TimelineIndicator/><TimelineContent>{{ label }}</TimelineContent></TimelineItem></Timeline></Card></template>
